+func TestNewContextLogger(t *testing.T) {
+	baseLogger := &mockLogger{}
+	ctx := t.Context()
+
+	ctxLogger := NewContextLogger(ctx, baseLogger)
+
+	assert.Equal(t, baseLogger, ctxLogger.base)
+	assert.Equal(t, ctx, ctxLogger.ctx)
